   "content": "#!/usr/bin/env bash
# Reproduction: two literal backslashes before a placeholder used to render
# "\15%" (escaped backslash + live placeholder). After 3b4be42 the characters
# are processed by MiniMessage *and* by the char-level placeholder pass, so the
# placeholder is treated as escaped and both backslashes vanish.
set -e
ROOT=${ROOT:-/work/repo}
SESSION_SRC=${SESSION_SRC:-$ROOT/src/main/java/me/rakkoon69/rakunminiitems/enchant/EnchantSession.java}
JDK=$(ls -d "$HOME"/.gradle/jdks/eclipse_adoptium-25* 2>/dev/null | head -1)
[ -n "$JDK" ] || JDK=$(dirname "$(dirname "$(readlink -f "$(command -v javac)")")")
CP=$(find "$HOME/.gradle/caches/modules-2" -name '*.jar' ! -name '*-sources.jar' ! -name '*-javadoc.jar' | paste -sd: -)
OUT=$(mktemp -d)
"$JDK/bin/javac" -nowarn -d "$OUT" -cp "$CP" -sourcepath "$ROOT/src/main/java" "$SESSION_SRC"
cat > "$OUT/ReproEscape.java" <<'JAVA'
import me.rakkoon69.rakunminiitems.enchant.EnchantSession;
import me.rakkoon69.rakunminiitems.group.ItemCatalog;
import me.rakkoon69.rakunminiitems.group.ItemGroups;
import me.rakkoon69.rakunminiitems.rarity.Rarities;
import net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer;

import java.util.Map;
import java.util.Set;

public class ReproEscape {
    public static void main(String[] args) {
        ItemCatalog catalog = new ItemCatalog() {
            public boolean item(String key) { return true; }
            public Set<String> tag(String key) { return Set.of(); }
        };
        // YAML single quotes: the description literally contains TWO backslashes.
        EnchantSession session = EnchantSession.open(
                Map.of("vampirism.yml", "percent-per-level: 5\ndescription: 'Heals \\\\{heal}% of damage dealt.'"),
                ItemGroups.read(null, catalog), Rarities.read(null));
        String out = PlainTextComponentSerializer.plainText().serialize(
                session.description(Map.of("rakunminiitems:vampirism", 3), 200).get(0));
        String expected = "Heals \\15% of damage dealt.";
        if (!expected.equals(out)) {
            System.out.println("FAIL: Heals \\\\{heal}% -> got [" + out + "], expected [" + expected + "]");
            System.exit(1);
        }
        System.out.println("PASS: " + out);
    }
}
JAVA
"$JDK/bin/java" -cp "$OUT:$CP" "$OUT/ReproEscape.java"
",
   "cmd": "bash /tmp/repro-escape.sh"
  }
 },
